def wiggleMaxLength(nums):
    if not nums:
        return 0

    # Initialize up and down counters
    up = down = 1

    for i in range(1, len(nums)):
        if nums[i] > nums[i-1]:
            up = down + 1
        elif nums[i] < nums[i-1]:
            down = up + 1
        # If nums[i] == nums[i-1], no update needed (same as before)

    return max(up, down)
